/**
 * activity.ts — typed fetch wrapper for the Monitor Dashboard "Recent Activity"
 * feed (ticket #1129).
 *
 *   GET /api/v1/monitor/dashboard/activity
 *     — 200 + the standard monitor-bff envelope:
 *       { "data": { "items": [ { "id", "kind", "source",
 *                                "occurred_at", "status" }, ... ] } }
 *
 * monitor-bff has no monitor-domain tables yet, so this endpoint returns an
 * EMPTY feed today. This module's job is honest, typed plumbing: GET, unwrap
 * the envelope, map each snake_case item to the camelCase MonitorActivityItem
 * shape the UI reads, and sort newest-first HERE (the mapping layer never
 * trusts server ordering). It must NEVER fabricate an item — an empty feed in
 * maps to an empty array out. Mirrors dashboard.ts.
 */

import { parseError, unwrap } from "./client";

export interface MonitorActivityItem {
  readonly id: string;
  readonly kind: string;
  readonly source: string;
  readonly occurredAt: string;
  readonly status: string;
}

function asString(v: unknown): string {
  return String(v ?? "");
}

function mapItem(raw: Record<string, unknown>): MonitorActivityItem {
  return {
    id: asString(raw.id),
    kind: asString(raw.kind),
    source: asString(raw.source),
    occurredAt: asString(raw.occurred_at),
    status: asString(raw.status),
  };
}

/**
 * monitorDashboardActivity — GET /api/v1/monitor/dashboard/activity.
 *
 * Fetches the feed DTO, unwraps the `{ data: { items: [...] } }` envelope,
 * maps each snake_case item to camelCase, and returns the list sorted
 * newest-first by occurredAt. A missing / non-array `items` (the honest empty
 * state monitor-bff serves today) maps to an empty array. Never fabricates an
 * item.
 */
export async function monitorDashboardActivity(
  signal?: AbortSignal,
): Promise<MonitorActivityItem[]> {
  const res = await fetch("/api/v1/monitor/dashboard/activity", {
    credentials: "include",
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const root = unwrap(await res.json()) as Record<string, unknown>;
  const itemsRaw = root.items;
  if (!Array.isArray(itemsRaw)) return [];

  const items = itemsRaw.map((raw) =>
    mapItem(
      raw !== null && typeof raw === "object"
        ? (raw as Record<string, unknown>)
        : {},
    ),
  );

  // Sort newest-first HERE — server order is not trusted. String comparison on
  // ISO-8601 timestamps is chronological; a stable sort preserves input order
  // for equal timestamps.
  return items.sort((a, b) => (a.occurredAt < b.occurredAt ? 1 : a.occurredAt > b.occurredAt ? -1 : 0));
}


