/**
 * client.ts — shared fetch-response helpers for every monitor-mfe API module.
 *
 * Mirrors range-mfe's src/api/exercises.ts helpers (MonitorApiError /
 * parseError / unwrap / asNumber) so every monitor-bff caller unwraps the
 * same `{ data: ... }` envelope (writeJSON, services/monitor-bff/internal/
 * handlers/errors.go) and coerces numeric fields the same way.
 */

/** Thrown by any monitor-mfe API function on a non-2xx response. */
export class MonitorApiError extends Error {
  constructor(
    public readonly status: number,
    message: string,
    /**
     * The stable error `code` from monitor-bff's `{"error":{code,message}}`
     * envelope (e.g. "saved_search_limit_reached"), when present — lets a caller
     * distinguish two conditions that share an HTTP status (a 409 limit-reached
     * vs a 409 duplicate) without re-parsing the body. "" when absent.
     */
    public readonly code = "",
    /**
     * Seconds the provider asked us to wait before retrying — parsed from the
     * `Retry-After` response header on a 429 (#1138). Present ONLY when the
     * header carried a positive integer; the Web path never sets it, so it
     * stays undefined for every existing caller. useNewsSearch drives its live
     * retry countdown from this value.
     */
    public readonly retryAfter?: number,
  ) {
    super(message);
    this.name = "MonitorApiError";
  }
}

/**
 * parseRetryAfter — read the `Retry-After` response header as a positive
 * integer number of seconds (#1138). Returns undefined when the header is
 * absent, non-numeric, or not strictly positive (a 0/negative delay carries no
 * meaningful countdown). Only the integer-seconds form is handled — monitor-bff
 * always emits seconds (never the HTTP-date form) for this path.
 */
function parseRetryAfter(res: Response): number | undefined {
  const raw = res.headers.get("Retry-After");
  if (raw === null) return undefined;
  const seconds = Number(raw);
  return Number.isInteger(seconds) && seconds > 0 ? seconds : undefined;
}

/**
 * parseError — build a MonitorApiError from a non-ok Response. monitor-bff
 * emits `{"error":{"code":...,"message":...}}` (errors.go's errorBody); this
 * also tolerates a bare string `error` (back-compat with range-bff's shape,
 * which this module mirrors) and a missing/non-JSON body, falling back to
 * `HTTP <status>`.
 *
 * NOTE for reviewers: the malformed/string/fallback branches below mirror
 * range-mfe's exercises.ts parseError, which has a dedicated parseError
 * describe block (tests/api/exercises.test.ts) covering exactly these paths.
 * monitor-mfe's own tests/api/client.test.ts covers the same branches here —
 * the well-formed object shape, the bare-string shape, and the
 * missing/non-JSON fallback.
 */
export async function parseError(res: Response): Promise<MonitorApiError> {
  let message = `HTTP ${res.status}`;
  let code = "";
  try {
    const body = (await res.json()) as { error?: unknown };
    const err = body.error;
    if (
      err !== null &&
      typeof err === "object" &&
      typeof (err as { message?: unknown }).message === "string"
    ) {
      message = (err as { message: string }).message;
      const c = (err as { code?: unknown }).code;
      if (typeof c === "string") code = c;
    } else if (typeof err === "string" && err !== "") {
      message = err;
    }
  } catch {
    // Body wasn't JSON (or was empty) — keep the HTTP-status fallback.
  }
  return new MonitorApiError(res.status, message, code, parseRetryAfter(res));
}

/**
 * unwrap — monitor-bff wraps every success payload in a top-level
 * `{ "data": payload }` envelope (writeJSON). Tolerates both the wrapped
 * shape and a flat shape by returning `body.data` when it's a non-null
 * object, else `body` itself.
 */
export function unwrap(body: unknown): unknown {
  const b = (body ?? {}) as Record<string, unknown>;
  const inner = b.data;
  return inner !== null && typeof inner === "object" ? inner : b;
}

/**
 * asNumber — coerce an unknown numeric value, falling back to `fallback`
 * (default 0). Non-finite / NaN / non-number inputs return the fallback.
 */
export function asNumber(v: unknown, fallback = 0): number {
  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
}

/**
 * asString — coerce an unknown value to a string, mapping null/undefined to
 * the empty string. A real `string` passes through unchanged; anything else is
 * stringified via String(). Mirrors activity.ts's local helper, promoted here
 * so every API module maps snake_case string fields the same way.
 */
export function asString(v: unknown): string {
  if (typeof v === "string") return v;
  if (v === null || v === undefined) return "";
  return String(v);
}


