/**
 * collectedTrends.ts — typed fetch wrapper for one monitor's collected-trends
 * board (#1144).
 *
 *   GET /api/v1/monitor/trends/{id}/collected
 *
 * Goes through monitor-bff and shares the standard `{ data: ... }` envelope
 * (see client.ts). The snake_case board DTO maps to the camelCase shape the
 * board components read. Mirrors api/trends.ts conventions (unwrap, parseError,
 * defensive coercion of every field).
 *
 * The board is honest by construction: `collected:false` (google/x/tiktok
 * today, which have no collector) comes through with empty rows and all-zero
 * counters — the UI renders a "not collected yet" state, never faked rows. A
 * row whose volume X did not report keeps `volumeReported:false`, so the volume
 * cell is muted rather than a fabricated 0.
 */

import { asNumber, asString, parseError, unwrap } from "./client";
import type { TrendPlatform } from "./trends";

/** Movement of a term's rank since the previous snapshot. */
export type TrendDelta = "new" | "up" | "down" | "same";

/** The six fixed volume bands, ascending. */
export type VolumeBand =
  | "lt_10k"
  | "10k_50k"
  | "50k_100k"
  | "100k_500k"
  | "500k_1m"
  | "gt_1m";

/** One ranked term in the Trending Now list (camelCase). */
export interface CollectedTrend {
  readonly rank: number;
  readonly term: string;
  readonly volume: number;
  /** false ⇒ volume not reported (render muted, never a fake 0). */
  readonly volumeReported: boolean;
  readonly delta: TrendDelta;
  /** Movement magnitude; only present for up/down (deferred feature). */
  readonly deltaBy?: number;
  /** Related/associated terms for this row; always present ([] when none). */
  readonly relatedTerms: readonly string[];
}

export interface TrendCounters {
  readonly total: number;
  readonly rising: number;
  readonly declining: number;
  readonly newEntries: number;
}

export interface DistributionBand {
  readonly band: VolumeBand;
  readonly count: number;
}

/** The whole collected-trends board for one monitor (camelCase). */
export interface CollectedBoard {
  /** false ⇒ nothing collected yet (honest empty state). */
  readonly collected: boolean;
  readonly platform: TrendPlatform;
  /** true ⇒ no prior snapshot; all rows NEW, velocity hint shown. */
  readonly firstSnapshot: boolean;
  /** ISO timestamp of the snapshot; "" when not collected. */
  readonly collectedAt: string;
  readonly rows: readonly CollectedTrend[];
  readonly counters: TrendCounters;
  readonly distribution: readonly DistributionBand[];
  /** Terms omitted from the distribution (no reported volume) — X footnote. */
  readonly unplotted: number;
}

// ─── mapping helpers ─────────────────────────────────────────────────────────

const WIRE_TO_PLATFORM: Record<string, TrendPlatform> = {
  google: "google",
  x: "x",
  tiktok: "tiktok",
  range: "range",
  PLATFORM_GOOGLE_TRENDS: "google",
  PLATFORM_X: "x",
  PLATFORM_TIKTOK: "tiktok",
  PLATFORM_RANGE_EXERCISE: "range",
};

const DELTAS: readonly TrendDelta[] = ["new", "up", "down", "same"];
const BANDS: readonly VolumeBand[] = [
  "lt_10k",
  "10k_50k",
  "50k_100k",
  "100k_500k",
  "500k_1m",
  "gt_1m",
];

function asRecord(v: unknown): Record<string, unknown> {
  return v !== null && typeof v === "object"
    ? (v as Record<string, unknown>)
    : {};
}

/** A read-tolerant string array: non-arrays → [], non-string members dropped. */
function asStringArray(v: unknown): string[] {
  return Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : [];
}

/** Unknown/unspecified platform ⇒ "google" (the honest, safe default). */
function toPlatform(raw: unknown): TrendPlatform {
  return WIRE_TO_PLATFORM[String(raw ?? "")] ?? "google";
}

/** Unknown delta ⇒ "same" (a neutral, honest fallback — no faked movement). */
function toDelta(raw: unknown): TrendDelta {
  const found = DELTAS.find((d) => d === raw);
  return found ?? "same";
}

function toBand(raw: unknown): VolumeBand {
  const found = BANDS.find((b) => b === raw);
  return found ?? "lt_10k";
}

function mapRow(raw: Record<string, unknown>): CollectedTrend {
  const volumeReported = raw.volume_reported === true;
  const base: CollectedTrend = {
    rank: asNumber(raw.rank),
    term: asString(raw.term),
    volume: asNumber(raw.volume),
    volumeReported,
    delta: toDelta(raw.delta),
    // Always present as an array — [] when the wire omits it or sends none.
    relatedTerms: asStringArray(raw.related_terms),
  };
  // delta_by is present only for real up/down movement (deferred). Attach it
  // only when it's a finite number, so an absent field stays undefined.
  return typeof raw.delta_by === "number" && Number.isFinite(raw.delta_by)
    ? { ...base, deltaBy: raw.delta_by }
    : base;
}

function mapCounters(raw: unknown): TrendCounters {
  const c = asRecord(raw);
  return {
    total: asNumber(c.total),
    rising: asNumber(c.rising),
    declining: asNumber(c.declining),
    newEntries: asNumber(c.new_entries),
  };
}

function mapDistribution(raw: unknown): DistributionBand[] {
  if (!Array.isArray(raw)) return [];
  return raw.map((item) => {
    const r = asRecord(item);
    return { band: toBand(r.band), count: asNumber(r.count) };
  });
}

/** GET /api/v1/monitor/trends/{id}/collected — one monitor's board. */
export async function listCollectedTrends(
  monitorId: string,
  signal?: AbortSignal,
): Promise<CollectedBoard> {
  const res = await fetch(
    `/api/v1/monitor/trends/${encodeURIComponent(monitorId)}/collected`,
    { credentials: "include", signal },
  );
  if (!res.ok) throw await parseError(res);

  const root = unwrap(await res.json()) as Record<string, unknown>;
  const rows = Array.isArray(root.rows)
    ? root.rows.map((r) => mapRow(asRecord(r)))
    : [];

  return {
    collected: root.collected === true,
    platform: toPlatform(root.platform),
    firstSnapshot: root.first_snapshot === true,
    collectedAt: asString(root.collected_at),
    rows,
    counters: mapCounters(root.counters),
    distribution: mapDistribution(root.distribution),
    unplotted: asNumber(root.unplotted),
  };
}


