/**
 * dashboard.ts — typed fetch wrapper for the Monitor Dashboard quick-stat
 * tiles (ticket #1128).
 *
 *   GET /api/v1/monitor/dashboard/stats
 *     — 200 + the standard monitor-bff envelope:
 *       { "data": { "stats": { "active_monitors": 0, "listening_monitors": 0,
 *                              "posts_tracked": 0, "people_tracked": 0 } } }
 *
 * services/monitor-bff/internal/handlers/dashboard_stats.go is a THIN
 * endpoint today — every count is a hardcoded zero (the monitor domain
 * tables don't exist yet). This module's job is honest, typed plumbing: GET,
 * unwrap the envelope, coerce each snake_case field to a number, map to the
 * camelCase MonitorDashboardStats shape the UI reads. It must NEVER
 * fabricate a non-zero count — see the HONESTY invariant on
 * useMonitorDashboardStats and StatTileRow.
 */

import { asNumber, parseError, unwrap } from "./client";

export interface MonitorDashboardStats {
  readonly activeMonitors: number;
  readonly listeningMonitors: number;
  readonly postsTracked: number;
  readonly peopleTracked: number;
}

/**
 * hasCollectingData — true when the workspace has at least one monitor actively
 * collecting, so the Monitoring summary card should show its "collecting" state
 * rather than the idle empty state (ticket #1131).
 *
 * Scaffold only: returns false unconditionally so imports compile and the
 * failing tests can reference it before the real logic lands.
 */
export function hasCollectingData(_stats: MonitorDashboardStats): boolean {
  // TODO(green #1131): derive from the stats DTO once the "collecting" signal
  // exists on the wire (e.g. activeMonitors > 0). Honest all-zero DTO today.
  return false;
}

/**
 * monitorDashboardStats — GET /api/v1/monitor/dashboard/stats.
 *
 * Fetches the quick-stat DTO, unwraps the `{ data: { stats: {...} } }`
 * envelope (unwrap() peels `data`, then `.stats` is read directly), and
 * coerces each snake_case count into the camelCase MonitorDashboardStats
 * shape the UI reads. Never fabricates a non-zero count — every field flows
 * straight from the response via asNumber(), so the honest all-zero DTO
 * monitor-bff serves today maps to an honest all-zero result.
 */
export async function monitorDashboardStats(
  signal?: AbortSignal,
): Promise<MonitorDashboardStats> {
  const res = await fetch("/api/v1/monitor/dashboard/stats", {
    credentials: "include",
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const root = unwrap(await res.json()) as Record<string, unknown>;
  const statsRaw = root.stats;
  const s: Record<string, unknown> =
    statsRaw !== null && typeof statsRaw === "object"
      ? (statsRaw as Record<string, unknown>)
      : {};

  return {
    activeMonitors: asNumber(s.active_monitors),
    listeningMonitors: asNumber(s.listening_monitors),
    postsTracked: asNumber(s.posts_tracked),
    peopleTracked: asNumber(s.people_tracked),
  };
}


