/**
 * posts.ts — typed fetch wrapper for the Monitor Posts surface (#1171).
 *
 *   GET /api/v1/monitor/tracked-posts — list the user's tracked posts
 *
 * The call goes through monitor-bff and shares the standard `{ data: ... }`
 * envelope (see client.ts). The BFF route is an honest-empty scaffold today —
 * no post-tracking tables exist yet, so it always returns `{data:{posts:[]}}`.
 * The snake_case → camelCase row mapper below is nonetheless real: it is the
 * seam #1173 builds the actual row cells (metrics, per-row actions, View Post)
 * on top of, so a populated response maps correctly the day the backend lands.
 * Every field is loose/best-effort on read (coerced via `asString`) because a
 * scaffold row may arrive with any subset of columns filled.
 */

import { asString, parseError, unwrap } from "./client";

/** A tracked post as the UI reads it (camelCase). Minimal for the shell — the
 *  real, richer shape (metric counts, comment rollups, per-row status) is #1173.
 *  Kept as a real seam, not a placeholder, so the mapper is the extension point. */
export interface TrackedPost {
  readonly id: string;
  /** Source platform id (e.g. "x", "tiktok"); free-form until #1173 pins an enum. */
  readonly platform: string;
  /** The author's handle/username on the source platform. */
  readonly authorHandle: string;
  /** Canonical URL of the tracked post. */
  readonly url: string;
  /** How often the post is re-checked (e.g. "hourly"). */
  readonly frequency: string;
  /** ISO timestamp of the last metrics check; blank until first checked. */
  readonly lastCheckedAt: string;
  /** Tracking status (e.g. "active", "paused"). */
  readonly status: string;
}

function asRecord(v: unknown): Record<string, unknown> {
  return v !== null && typeof v === "object"
    ? (v as Record<string, unknown>)
    : {};
}

function mapPost(raw: Record<string, unknown>): TrackedPost {
  return {
    id: asString(raw.id),
    platform: asString(raw.platform),
    authorHandle: asString(raw.author_handle),
    url: asString(raw.url),
    frequency: asString(raw.frequency),
    lastCheckedAt: asString(raw.last_checked_at),
    status: asString(raw.status),
  };
}

/** GET /api/v1/monitor/tracked-posts — the user's tracked posts (empty ⇒ []). */
export async function listTrackedPosts(
  signal?: AbortSignal,
): Promise<TrackedPost[]> {
  const res = await fetch("/api/v1/monitor/tracked-posts", {
    credentials: "include",
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const root = unwrap(await res.json()) as Record<string, unknown>;
  const rows = root.posts;
  if (!Array.isArray(rows)) return [];
  return rows.map((r) => mapPost(asRecord(r)));
}


