/**
 * saveToFiles.ts — typed fetch wrappers for the Monitor "Save to Files" flow
 * (ticket #1139). A search/scrape result's in-hand markdown is filed into a
 * Files-domain corpus (a "collection") and optionally a folder, via monitor-bff.
 *
 * Two of these routes read the Files domain directly (list the workspace's
 * corpora, list a corpus's top-level folders, create a folder), and one posts
 * the actual save through monitor-bff:
 *
 *   GET  /api/v1/files/workspace/corpora
 *     → { "data": { "corpora": [ { id, name, is_personal_inbox?, doc_count? } ],
 *                    "next_cursor" } }
 *   GET  /api/v1/files/corpora/{corpusId}/folders/tree?max_depth=1
 *     → { "data": { "root": { folder, children: [ { folder: {id,name,corpus_id},
 *                                                    children } ] } } }
 *   POST /api/v1/files/corpora/{corpusId}/folders  { name }
 *     → { "data": { id, name, corpus_id, ... } }  (the created folder)
 *   POST /api/v1/monitor/save-to-files
 *        { corpusId, folderId?, title, markdown, sourceDomain }
 *     → { "data": { id, filename, corpusId } }
 *
 * Honest plumbing, mirroring search.ts / scrape.ts: every request carries the
 * session cookie (`credentials: "include"`), unwraps the `{ data: ... }`
 * envelope, coerces string/number fields via asString / asNumber (a missing
 * field maps to "" / 0, never fabricated), and throws a MonitorApiError on any
 * non-2xx response. `signal` threads an AbortController so an overlapping /
 * cancelled request aborts in flight.
 */

import { asNumber, asString, parseError, unwrap } from "./client";

/** One workspace collection (Files corpus) the result can be saved into. */
export interface FilesCorpus {
  readonly id: string;
  readonly name: string;
  /** The user's personal "My Files" inbox — sorted first, default-selected. */
  readonly isPersonalInbox: boolean;
  /** Number of documents in the collection (0 when unknown). */
  readonly docCount: number;
}

/** One top-level folder within a collection (flat picker). */
export interface FilesFolder {
  readonly id: string;
  readonly name: string;
}

/** The monitor-bff save request body (#1139). */
export interface SaveToFilesBody {
  readonly corpusId: string;
  readonly folderId?: string;
  readonly title: string;
  readonly markdown: string;
  readonly sourceDomain: string;
}

/**
 * listWorkspaceCorpora — GET /api/v1/files/workspace/corpora.
 *
 * Maps each corpus row into a FilesCorpus, coercing id/name via asString,
 * docCount via asNumber, and reading the personal-inbox flag as strictly
 * `is_personal_inbox === true`. The personal inbox ("My Files") is sorted FIRST
 * (stable) so it is the natural default selection; the rest keep their server
 * order.
 */
export async function listWorkspaceCorpora(
  signal?: AbortSignal,
): Promise<FilesCorpus[]> {
  const res = await fetch("/api/v1/files/workspace/corpora", {
    method: "GET",
    credentials: "include",
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const d = unwrap(await res.json()) as Record<string, unknown>;
  const rows = Array.isArray(d.corpora) ? d.corpora : [];
  const corpora = rows.map((row): FilesCorpus => {
    const r = (row ?? {}) as Record<string, unknown>;
    return {
      id: asString(r.id),
      name: asString(r.name),
      isPersonalInbox: r.is_personal_inbox === true,
      docCount: asNumber(r.doc_count),
    };
  });
  // Personal inbox first, everything else in the server's order — a stable sort
  // keyed only on the inbox flag preserves the relative order of the rest.
  return corpora
    .map((c, i) => ({ c, i }))
    .sort((a, b) => {
      const rank = Number(b.c.isPersonalInbox) - Number(a.c.isPersonalInbox);
      return rank !== 0 ? rank : a.i - b.i;
    })
    .map(({ c }) => c);
}

/**
 * createWorkspaceCorpus — POST /api/v1/files/corpora  { name }.
 *
 * Creates a new workspace collection (Files corpus) and maps the created row
 * into a FilesCorpus. Used by the Save-to-Files modal's graceful empty state so
 * a workspace with NO collections yet can create its first one inline rather
 * than dead-ending. files-bff's corpus Create returns the row UNWRAPPED (a bare
 * `corpusJSON`, not a `{ data }` envelope) with a 201; `unwrap` tolerates both,
 * so the same coercions as listWorkspaceCorpora apply.
 */
export async function createWorkspaceCorpus(
  name: string,
  signal?: AbortSignal,
): Promise<FilesCorpus> {
  const res = await fetch("/api/v1/files/corpora", {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name }),
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const d = unwrap(await res.json()) as Record<string, unknown>;
  return {
    id: asString(d.id),
    name: asString(d.name),
    isPersonalInbox: d.is_personal_inbox === true,
    docCount: asNumber(d.doc_count),
  };
}

/**
 * listCorpusFolders — GET
 * /api/v1/files/corpora/{corpusId}/folders/tree?max_depth=1.
 *
 * Flattens the folder tree's TOP-LEVEL children into a flat picker list: reads
 * `root.children[].folder` → { id, name }. Returns [] when root/children are
 * missing or not an array, and skips any row whose id coerces to "" (a folder
 * with no usable id can't be selected).
 */
export async function listCorpusFolders(
  corpusId: string,
  signal?: AbortSignal,
): Promise<FilesFolder[]> {
  const res = await fetch(
    `/api/v1/files/corpora/${corpusId}/folders/tree?max_depth=1`,
    {
      method: "GET",
      credentials: "include",
      signal,
    },
  );
  if (!res.ok) throw await parseError(res);

  const d = unwrap(await res.json()) as Record<string, unknown>;
  const root = (d.root ?? {}) as Record<string, unknown>;
  const children = Array.isArray(root.children) ? root.children : [];
  const folders: FilesFolder[] = [];
  for (const child of children) {
    const node = (child ?? {}) as Record<string, unknown>;
    const folder = (node.folder ?? {}) as Record<string, unknown>;
    const id = asString(folder.id);
    if (id === "") continue;
    folders.push({ id, name: asString(folder.name) });
  }
  return folders;
}

/**
 * createCorpusFolder — POST /api/v1/files/corpora/{corpusId}/folders  { name }.
 *
 * Creates a top-level folder in the collection and returns the created row as a
 * FilesFolder (id + name). Used by the modal's "New folder" affordance.
 */
export async function createCorpusFolder(
  corpusId: string,
  name: string,
  signal?: AbortSignal,
): Promise<FilesFolder> {
  const res = await fetch(`/api/v1/files/corpora/${corpusId}/folders`, {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name }),
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const d = unwrap(await res.json()) as Record<string, unknown>;
  return { id: asString(d.id), name: asString(d.name) };
}

/**
 * saveToFiles — POST /api/v1/monitor/save-to-files.
 *
 * Files the in-hand markdown into the chosen collection (+ optional folder) via
 * monitor-bff, returning the created document's id. `folderId` reaches the body
 * only when set (undefined = save at the collection root). Throws a
 * MonitorApiError on any non-2xx response.
 */
export async function saveToFiles(
  body: SaveToFilesBody,
  signal?: AbortSignal,
): Promise<string> {
  const wire: Record<string, unknown> = {
    corpusId: body.corpusId,
    title: body.title,
    markdown: body.markdown,
    sourceDomain: body.sourceDomain,
  };
  if (body.folderId !== undefined && body.folderId !== "") {
    wire.folderId = body.folderId;
  }
  const res = await fetch("/api/v1/monitor/save-to-files", {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(wire),
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const d = unwrap(await res.json()) as Record<string, unknown>;
  // monitor-bff returns the created row as { id, filename, corpusId } — the wire
  // field is `id`, not `documentId` (the hook keeps `documentId` as its own
  // client-side state name).
  return asString(d.id);
}


