/**
 * search.ts — typed fetch wrapper for Monitor Web search (ticket #1134).
 *
 *   POST /api/v1/monitor/search  { query, count?, countryCode?, timeRange?,
 *     safeSearch?, domain?, resultType?, targetLocale? }   (ticket #1135)
 *     — 200 + the standard monitor-bff envelope:
 *       { "data": { "results": [ { title, url, snippet, sourceDomain,
 *                                  sourceLanguage?, thumbnailUrl? } ], "engine" } }
 *     — non-2xx: monitor-bff's { "error": { code, message } }; HTTP 429 means
 *       the provider is throttling, 503 means it's unavailable. Both surface as
 *       a MonitorApiError carrying the status so useWebSearch can map the two
 *       apart (throttle vs unavailable) without re-parsing the body.
 *   GET  /api/v1/monitor/search/providers → { "data": { "serperAvailable" } }.
 *
 * Honest plumbing, mirroring scrape.ts: POST the query (+ optional count) as
 * JSON with the session cookie, unwrap the envelope, and coerce each row's
 * string fields via asString so a missing field maps to "" (never fabricated).
 * `signal` threads an AbortController so an overlapping / cancelled search
 * aborts in flight.
 */

import { asNumber, asString, parseError, unwrap } from "./client";
import type { SearchSource } from "../components/SearchEmptyState";
import type { SearchFilterValues } from "../components/FiltersPanel";

/** Web search result Type filter — Serper endpoint/branch (ticket #1135). */
export type ResultType =
  | "general"
  | "images"
  | "academic"
  | "articles"
  | "broadcast"
  | "videos";

/** Recency filter (→ Serper `tbs=qdr:*`). */
export type TimeRange = "any" | "day" | "week" | "month" | "year";

/** Safe-search state (Web only; → Serper safe param). */
export type SafeSearch = "on" | "off";

/**
 * WebSearchOptions — the filter / country / locale knobs threaded into a
 * search request (ticket #1135). Every field is optional; only a field that is
 * actually SET reaches the wire (worldwide = omit countryCode, "any"/"general"
 * are omitted, a blank/whitespace domain is omitted). `targetLocale` is the
 * current UI locale, so the backend knows which language to translate into.
 */
export interface WebSearchOptions {
  /** Number of results requested (Serper `num`). */
  readonly count?: number;
  /** ISO-3166-1 alpha-2 country scope (Serper `gl`); omit for Worldwide. */
  readonly countryCode?: string;
  /** Recency window; "any" is omitted. */
  readonly timeRange?: TimeRange;
  /** Safe search; sent verbatim ("on"/"off") when provided. */
  readonly safeSearch?: SafeSearch;
  /** Single-site restriction (Serper `site:`); blank is omitted. */
  readonly domain?: string;
  /** Result type / endpoint branch; "general" is omitted. */
  readonly resultType?: ResultType;
  /** UI locale to translate foreign results into (e.g. "es-419"). */
  readonly targetLocale?: string;
}

/** One web search result row — readonly, UI-facing shape. */
export interface WebResult {
  /** Result title / headline. */
  readonly title: string;
  /** The result's canonical URL (rendered behind safeHref at the sink). */
  readonly url: string;
  /** A short snippet / excerpt describing the result. */
  readonly snippet: string;
  /** The source host (e.g. "example.com"), shown as the result's source badge. */
  readonly sourceDomain: string;
  /**
   * The ISO-639-1 language the result was ORIGINALLY in — present ONLY when the
   * backend translated the title/snippet into the user's locale. Its presence
   * is exactly the signal to render the "Translated from {language}" badge; an
   * untranslated row leaves it undefined (never "").
   */
  readonly sourceLanguage?: string;
  /**
   * The result's thumbnail image URL — present ONLY for an image result
   * (ticket #1135). Its presence is exactly the signal to render the image on
   * the card, and the client NEVER loads it directly: it is fetched through the
   * BFF image-proxy (privacy / no-track). An absent thumbnail leaves it
   * undefined (never "").
   */
  readonly thumbnailUrl?: string;
  /**
   * The full-size image's pixel width — present ONLY for an image result that
   * carries dimensions (#2994, "where available"). Threaded through so the
   * image detail panel can show a Dimensions spec; a row without it leaves the
   * field undefined (never 0).
   */
  readonly imageWidth?: number;
  /** The full-size image's pixel height — see imageWidth (#2994). */
  readonly imageHeight?: number;
  /**
   * The video's human-readable runtime (e.g. "4:12") — present ONLY for a video
   * result (#3034). Threaded through so the row list and the detail panel can
   * show a Runtime spec; a row without it leaves the field undefined (never "").
   */
  readonly duration?: string;
  /**
   * The video's source channel / uploader name — present ONLY for a video
   * result (#3034). A row without it leaves the field undefined (never "").
   */
  readonly channel?: string;
  /**
   * The video's published date, as the provider supplies it (e.g. "3 days ago")
   * — present ONLY for a video result (#3034). A row without it leaves the field
   * undefined (never "").
   */
  readonly published?: string;
}

/** The result of a successful web search. */
export interface WebSearchResponse {
  readonly results: WebResult[];
  /** Which provider engine produced the results (e.g. "serper"). */
  readonly engine: string;
}

/** Provider availability, read by the surface to explain an unavailable state. */
export interface SearchProviders {
  readonly serperAvailable: boolean;
}

function coerceResult(row: unknown): WebResult {
  const r = (row ?? {}) as Record<string, unknown>;
  // sourceLanguage is present only for a translated row — coerce it, and drop
  // an empty result so an untranslated row's field stays undefined, not "".
  const sourceLanguage = asString(r.sourceLanguage);
  // thumbnailUrl is present only for an image result — coerce it, and drop an
  // empty value so a non-image row's field stays undefined, not "".
  const thumbnailUrl = asString(r.thumbnailUrl);
  // imageWidth/imageHeight are present only for a sized image result — coerce
  // them, and drop a non-positive value so an absent/0 dimension stays
  // undefined, not 0 (#2994, "where available").
  const imageWidth = asNumber(r.imageWidth);
  const imageHeight = asNumber(r.imageHeight);
  // duration/channel/published are present only for a video result (#3034) —
  // coerce each and drop an empty value so a non-video row's field stays
  // undefined, not "".
  const duration = asString(r.duration);
  const channel = asString(r.channel);
  const published = asString(r.published);
  return {
    title: asString(r.title),
    url: asString(r.url),
    snippet: asString(r.snippet),
    sourceDomain: asString(r.sourceDomain),
    ...(sourceLanguage !== "" ? { sourceLanguage } : {}),
    ...(thumbnailUrl !== "" ? { thumbnailUrl } : {}),
    ...(imageWidth > 0 ? { imageWidth } : {}),
    ...(imageHeight > 0 ? { imageHeight } : {}),
    ...(duration !== "" ? { duration } : {}),
    ...(channel !== "" ? { channel } : {}),
    ...(published !== "" ? { published } : {}),
  };
}

/**
 * buildSearchBody — assemble the request body per the BFF contract, including a
 * field ONLY when it is meaningfully set: worldwide omits countryCode, "any"
 * time / "general" type are omitted, a blank/whitespace domain is omitted, and
 * count/safeSearch/targetLocale are included whenever supplied.
 */
function buildSearchBody(
  query: string,
  options: WebSearchOptions,
): Record<string, unknown> {
  const body: Record<string, unknown> = { query };
  if (options.count !== undefined) body.count = options.count;
  if (options.countryCode) body.countryCode = options.countryCode;
  if (options.timeRange !== undefined && options.timeRange !== "any") {
    body.timeRange = options.timeRange;
  }
  if (options.safeSearch !== undefined) body.safeSearch = options.safeSearch;
  const domain = options.domain?.trim() ?? "";
  if (domain !== "") body.domain = domain;
  if (options.resultType !== undefined && options.resultType !== "general") {
    body.resultType = options.resultType;
  }
  if (options.targetLocale) body.targetLocale = options.targetLocale;
  return body;
}

/**
 * executeWebSearch — POST /api/v1/monitor/search.
 *
 * Sends `{ query, ...filters/country/locale }` as JSON with the session cookie,
 * throws a MonitorApiError (carrying the HTTP status) on any non-2xx response,
 * and maps the success envelope into a WebSearchResponse. Each optional field
 * reaches the body only when meaningfully set (see buildSearchBody). A missing
 * / non-array `results` maps to an empty list.
 */
export async function executeWebSearch(
  query: string,
  options?: WebSearchOptions,
  signal?: AbortSignal,
): Promise<WebSearchResponse> {
  const res = await fetch("/api/v1/monitor/search", {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(buildSearchBody(query, options ?? {})),
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const d = unwrap(await res.json()) as Record<string, unknown>;
  const rows = Array.isArray(d.results) ? d.results : [];
  return {
    results: rows.map(coerceResult),
    engine: asString(d.engine),
  };
}

/**
 * getSearchProviders — GET /api/v1/monitor/search/providers.
 *
 * Reports whether the web-search provider (Serper) is configured, so the
 * surface can proactively render its "unavailable" state before a search is
 * ever run. Coerces a missing / non-boolean `serperAvailable` to `false`
 * (assume unavailable).
 */
export async function getSearchProviders(
  signal?: AbortSignal,
): Promise<SearchProviders> {
  const res = await fetch("/api/v1/monitor/search/providers", {
    method: "GET",
    credentials: "include",
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const d = unwrap(await res.json()) as Record<string, unknown>;
  return { serperAvailable: d.serperAvailable === true };
}

// ─── Saved searches (#1136 save / #1137 manage) ─────────────────────────────
//
// One saved query persists the exact source + query + filter set so it can be
// re-loaded (hydrate the surface, no network) or re-executed. The wire is
// camelCase JSON, matching executeWebSearch, so the mapper coerces each field
// and normalizes the enum-ish strings to a valid value with an honest default.
// safeSearch + country are OPTIONAL: absent/empty ⇒ undefined in the UI shape
// (never a fabricated "off"/""), and on create they reach the body only when set.

const SAVED_SEARCHES_URL = "/api/v1/monitor/saved-searches";

/**
 * The stable BFF error `code` a Create carries when the org is already at the
 * per-org saved-query cap (HTTP 409). The save flow keys the "limit reached"
 * message off this exact code so it can tell the cap apart from other 409s
 * (e.g. a duplicate). Kept in sync with monitor-bff's search_saved.go.
 */
export const SAVED_SEARCH_LIMIT_REACHED_CODE = "saved_search_limit_reached";

const SOURCES: readonly SearchSource[] = ["web", "news", "range"];
const RESULT_TYPES: readonly ResultType[] = [
  "general",
  "images",
  "academic",
  "articles",
  "broadcast",
  "videos",
];
const TIME_RANGES: readonly TimeRange[] = ["any", "day", "week", "month", "year"];

/** A saved search as the UI reads it (camelCase). */
export interface SavedSearch {
  readonly id: string;
  readonly name: string;
  readonly description: string;
  readonly query: string;
  readonly source: SearchSource;
  readonly resultType: ResultType;
  readonly count: number;
  readonly timeRange: TimeRange;
  /** Web-only; undefined = unspecified (provider default). */
  readonly safeSearch?: SafeSearch;
  readonly domain: string;
  /** ISO country scope; undefined = Worldwide. */
  readonly country?: string;
  readonly targetLocale: string;
  readonly executionCount: number;
  /** ISO timestamp of the last execution; "" = never executed. */
  readonly lastExecutedAt: string;
  readonly createdAt: string;
  readonly updatedAt: string;
}

/** The create-request body (#1136). safeSearch / country are omitted when unset. */
export interface SavedSearchCreateBody {
  readonly name: string;
  readonly description: string;
  readonly query: string;
  readonly source: SearchSource;
  readonly resultType: ResultType;
  readonly count: number;
  readonly timeRange: TimeRange;
  readonly safeSearch?: SafeSearch;
  readonly domain: string;
  readonly country?: string;
  readonly targetLocale: string;
}

/**
 * The update-request body (partial overwrite). Every field is optional: an
 * undefined key is NOT sent (leave unchanged). A field that IS sent carries a
 * CONCRETE value — never `null`. Clearing safeSearch / country is expressed as
 * `"unspecified"` / `""` (empty = Worldwide), not JSON null: Go's encoding/json
 * decodes BOTH an absent key AND a `null` to a nil pointer, so a null would be
 * indistinguishable from "not provided" at the BFF and the stale value would
 * silently survive. A concrete present value overwrites unambiguously.
 */
export interface SavedSearchUpdateBody {
  readonly name?: string;
  readonly description?: string;
  readonly query?: string;
  readonly source?: SearchSource;
  readonly resultType?: ResultType;
  readonly count?: number;
  readonly timeRange?: TimeRange;
  readonly safeSearch?: SafeSearch | "unspecified";
  readonly domain?: string;
  readonly country?: string;
  readonly targetLocale?: string;
}

function toSource(raw: unknown): SearchSource {
  return SOURCES.includes(raw as SearchSource) ? (raw as SearchSource) : "web";
}

function toResultType(raw: unknown): ResultType {
  return RESULT_TYPES.includes(raw as ResultType)
    ? (raw as ResultType)
    : "general";
}

function toTimeRange(raw: unknown): TimeRange {
  return TIME_RANGES.includes(raw as TimeRange) ? (raw as TimeRange) : "any";
}

/** "on"/"off" ⇒ that value; anything else (absent/"") ⇒ undefined. */
function toSafeSearch(raw: unknown): SafeSearch | undefined {
  return raw === "on" || raw === "off" ? raw : undefined;
}

/** A non-empty string ⇒ that string; absent/"" ⇒ undefined (Worldwide). */
function toOptionalString(raw: unknown): string | undefined {
  const s = asString(raw);
  return s === "" ? undefined : s;
}

function mapSavedSearch(raw: unknown): SavedSearch {
  const r = (raw ?? {}) as Record<string, unknown>;
  const safeSearch = toSafeSearch(r.safeSearch);
  const country = toOptionalString(r.country);
  return {
    id: asString(r.id),
    name: asString(r.name),
    description: asString(r.description),
    query: asString(r.query),
    source: toSource(r.source),
    resultType: toResultType(r.resultType),
    count: asNumber(r.count),
    timeRange: toTimeRange(r.timeRange),
    domain: asString(r.domain),
    targetLocale: asString(r.targetLocale),
    executionCount: asNumber(r.executionCount),
    lastExecutedAt: asString(r.lastExecutedAt),
    createdAt: asString(r.createdAt),
    updatedAt: asString(r.updatedAt),
    ...(safeSearch !== undefined ? { safeSearch } : {}),
    ...(country !== undefined ? { country } : {}),
  };
}

/** The SearchRoute state a saved search is composed from / restored into. */
export interface SavedSearchDraft {
  readonly query: string;
  readonly source: SearchSource;
  readonly filters: SearchFilterValues;
  /**
   * The saved result language (#1136 bug A). LOAD/RUN restores this into the
   * surface so a re-execution back-translates results into the SAVED language,
   * not the editor's current UI locale (`getLocale()`).
   */
  readonly targetLocale: string;
}

/** Split a saved row back into the query + source + filter set for LOAD. */
export function savedSearchToDraft(saved: SavedSearch): SavedSearchDraft {
  return {
    query: saved.query,
    source: saved.source,
    targetLocale: saved.targetLocale,
    filters: {
      resultType: saved.resultType,
      count: saved.count,
      timeRange: saved.timeRange,
      safeSearch: saved.safeSearch,
      domain: saved.domain,
      country: saved.country,
    },
  };
}

/** The SearchRoute state a Save/Update reads from. */
export interface SavedSearchInput {
  readonly name: string;
  readonly description: string;
  readonly query: string;
  readonly source: SearchSource;
  readonly filters: SearchFilterValues;
  readonly targetLocale: string;
}

/**
 * Flatten the SearchRoute state + filter set into a create body (#1136).
 * safeSearch / country are included only when set (undefined = worldwide /
 * unspecified, omitted). The name is trimmed.
 */
export function buildSavedSearchCreateBody(
  input: SavedSearchInput,
): SavedSearchCreateBody {
  const { filters } = input;
  return {
    name: input.name.trim(),
    description: input.description,
    query: input.query,
    source: input.source,
    resultType: filters.resultType,
    count: filters.count,
    timeRange: filters.timeRange,
    domain: filters.domain,
    targetLocale: input.targetLocale,
    ...(filters.safeSearch !== undefined ? { safeSearch: filters.safeSearch } : {}),
    ...(filters.country !== undefined ? { country: filters.country } : {}),
  };
}

/**
 * Build a FULL overwrite update body from the SearchRoute state (#1137 "Update
 * existing"). Every field is sent as a CONCRETE value so the overwrite genuinely
 * replaces the whole persisted tuple: an unspecified safe search overwrites as
 * `"unspecified"` and a worldwide country as `""` (empty). Neither is ever sent
 * as JSON null — the BFF's Go decoder would fold a null into a nil pointer that
 * is indistinguishable from an absent key, leaving the stale value in place (the
 * "US→Worldwide never clears" bug). See SavedSearchUpdateBody.
 */
export function buildSavedSearchUpdateBody(
  input: SavedSearchInput,
): SavedSearchUpdateBody {
  const { filters } = input;
  return {
    name: input.name.trim(),
    description: input.description,
    query: input.query,
    source: input.source,
    resultType: filters.resultType,
    count: filters.count,
    timeRange: filters.timeRange,
    domain: filters.domain,
    targetLocale: input.targetLocale,
    safeSearch: filters.safeSearch ?? "unspecified",
    country: filters.country ?? "",
  };
}

/** GET /api/v1/monitor/saved-searches — the user's saved searches. */
export async function listSavedSearches(
  signal?: AbortSignal,
): Promise<SavedSearch[]> {
  const res = await fetch(SAVED_SEARCHES_URL, {
    credentials: "include",
    signal,
  });
  if (!res.ok) throw await parseError(res);
  const data = unwrap(await res.json());
  return Array.isArray(data) ? data.map(mapSavedSearch) : [];
}

/** POST /api/v1/monitor/saved-searches — create, return the created row. */
export async function createSavedSearch(
  body: SavedSearchCreateBody,
  signal?: AbortSignal,
): Promise<SavedSearch> {
  const res = await fetch(SAVED_SEARCHES_URL, {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
    signal,
  });
  if (!res.ok) throw await parseError(res);
  return mapSavedSearch(unwrap(await res.json()));
}

/**
 * PUT /api/v1/monitor/saved-searches/{id} — update. Only keys that are not
 * `undefined` reach the wire; every key that IS sent carries a concrete value
 * (a clear is `""` / `"unspecified"`, never null — see SavedSearchUpdateBody).
 */
export async function updateSavedSearch(
  id: string,
  body: SavedSearchUpdateBody,
  signal?: AbortSignal,
): Promise<SavedSearch> {
  const wire: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(body)) {
    if (value !== undefined) wire[key] = value;
  }
  const res = await fetch(`${SAVED_SEARCHES_URL}/${id}`, {
    method: "PUT",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(wire),
    signal,
  });
  if (!res.ok) throw await parseError(res);
  return mapSavedSearch(unwrap(await res.json()));
}

/** DELETE /api/v1/monitor/saved-searches/{id} — 204 on success. */
export async function deleteSavedSearch(
  id: string,
  signal?: AbortSignal,
): Promise<void> {
  const res = await fetch(`${SAVED_SEARCHES_URL}/${id}`, {
    method: "DELETE",
    credentials: "include",
    signal,
  });
  if (!res.ok) throw await parseError(res);
}

/**
 * POST /api/v1/monitor/saved-searches/{id}/execute — record an execution
 * (bumps executionCount / lastExecutedAt), return the updated row.
 */
export async function recordSavedSearchExecution(
  id: string,
  signal?: AbortSignal,
): Promise<SavedSearch> {
  const res = await fetch(`${SAVED_SEARCHES_URL}/${id}/execute`, {
    method: "POST",
    credentials: "include",
    signal,
  });
  if (!res.ok) throw await parseError(res);
  return mapSavedSearch(unwrap(await res.json()));
}


