/**
 * dashboard.ts — typed fetch wrapper for the Monitor Dashboard quick-stat
 * tiles (ticket #1128).
 *
 *   GET /api/v1/monitor/dashboard/stats
 *     — 200 + the standard monitor-bff envelope:
 *       { "data": { "stats": { "active_monitors": 0, "listening_monitors": 0,
 *                              "posts_tracked": 0, "people_tracked": 0 } } }
