--- frontends/monitor-mfe/src/api/news.ts (210 lines) ---
/**
 * news.ts — typed fetch wrapper for Monitor GDELT News search (ticket #1138).
 *
 *   POST /api/v1/monitor/news  { query, count?, countryCode?, timeRange?,
 *     domain?, resultType?, targetLocale? }   (NO safeSearch — News has none)
 *     — 200 + the standard monitor-bff envelope:
 *       { "data": { "results": [ { title, url, snippet, sourceDomain,
 *                                  sourceCountry?, sourceLanguage?, seenDate,
 *                                  thumbnailUrl? } ], "engine": "gdelt" } }
 *     — non-2xx: monitor-bff's { "error": { code, message } }; HTTP 429 means
 *       GDELT is throttling (may carry a `Retry-After` header, surfaced on
 *       MonitorApiError.retryAfter), 503 means unavailable. Both surface as a
 *       MonitorApiError carrying the status so useNewsSearch can map the two
 *       apart (throttle vs unavailable) without re-parsing the body.
 *   GET  /api/v1/monitor/news/coverage → { "data": { "articleCount" } } — the
 *     Home CoverageStrip's standing GDELT volume chip.
 *
 * A deliberate mirror of api/search.ts (see its header): POST the query (+
 * optional filters) as JSON with the session cookie, unwrap the `{ data }`
 * envelope, and coerce each row's string fields via asString so a missing field
 * maps to "" (never fabricated). Distinct from Web: there is no safeSearch, the
 * `articleDate` (`seenDate`) is ALWAYS present, and `sourceCountry` is a
 * News-only optional field.
 */

import { asNumber, asString, parseError, unwrap } from "./client";
import type { TimeRange } from "./search";

/**
 * NewsResultType — the class of GDELT news results. Only "articles" and
 * "images" are shippable; "broadcast" is DEFERRED (the service returns
 * UNIMPLEMENTED and the UI greys it), so it is accepted here only to be dropped
 * before the wire — it must NEVER reach monitor-bff.
 */
export type NewsResultType = "articles" | "images" | "broadcast";

/**
 * NewsSearchOptions — the filter / country / locale knobs threaded into a News
 * request. Every field is optional; only a field that is actually SET reaches
 * the wire (worldwide = omit countryCode, "any" time is omitted, a
 * blank/whitespace domain is omitted, the default "articles" type is omitted,
 * and "broadcast" is never sent). `targetLocale` is the current UI locale so
 * the backend knows which language to translate each article into.
 */
export interface NewsSearchOptions {
  /** Number of results requested (GDELT maxrecords). */
  readonly count?: number;
  /** ISO-3166-1 alpha-2 country scope (mapped to GDELT FIPS sourcecountry at
   * the service); omit for Worldwide. */
  readonly countryCode?: string;
  /** Recency window; "any" is omitted. */
  readonly timeRange?: TimeRange;
  /** Single-site restriction appended to the GDELT query; blank is omitted. */
  readonly domain?: string;
  /** Result type / GDELT mode; the "articles" default and "broadcast" are omitted. */
  readonly resultType?: NewsResultType;
  /** UI locale to translate foreign articles into (e.g. "es-419"). */
  readonly targetLocale?: string;
}

/** One GDELT news article — readonly, UI-facing shape. */
export interface NewsResult {
  /** Article headline. */
  readonly title: string;
  /** The article's canonical URL (rendered behind safeHref at the sink). */
  readonly url: string;
  /**
   * A short excerpt. GDELT's ArtList provides no per-article snippet, so this
   * MAY be "" — the card degrades gracefully to a title-only row.
   */
  readonly snippet: string;
  /** The publisher domain (leading "www." stripped), shown as the source badge. */
  readonly sourceDomain: string;
  /**
   * The article's date (RFC3339 UTC, from GDELT's seendate) — ALWAYS present.
   * REQUIRED for the AC: every News card shows the article date.
   */
  readonly seenDate: string;
  /**
   * The publisher's country — a News-only optional field. Present only when
   * GDELT reports it; an absent value leaves it undefined (never "").
   */
  readonly sourceCountry?: string;
  /**
   * The ISO-639-1 language the article was ORIGINALLY in — present ONLY when the
   * backend translated the title into the user's locale. Its presence is exactly
   * the signal to render the "Translated from {language}" badge; an untranslated
   * row leaves it undefined (never "").
   */
  readonly sourceLanguage?: string;
  /**
   * The article's social image URL — present ONLY for an IMAGES-type result.
   * Its presence is exactly the signal to render the image on the card, and the
   * client NEVER loads it directly: it is fetched through the BFF image-proxy
   * (privacy / no-track). An absent image leaves it undefined (never "").
   */
  readonly thumbnailUrl?: string;
}

/** The result of a successful News search. */
export interface NewsSearchResponse {
  readonly results: NewsResult[];
  /** Which provider engine produced the results ("gdelt"). */
  readonly engine: string;
}

/** The Home CoverageStrip's standing GDELT article volume. */
export interface NewsCoverage {
  /** Recent GDELT article count for the coverage chip. */
  readonly articleCount: number;
}

function coerceResult(row: unknown): NewsResult {
  const r = (row ?? {}) as Record<string, unknown>;
  // Optional fields are present only sometimes — coerce, then drop an empty
  // value so an absent field stays undefined, not "".
  const sourceCountry = asString(r.sourceCountry);
  const sourceLanguage = asString(r.sourceLanguage);
  const thumbnailUrl = asString(r.thumbnailUrl);
  return {
    title: asString(r.title),
    url: asString(r.url),
    snippet: asString(r.snippet),
    sourceDomain: asString(r.sourceDomain),
    // seenDate is REQUIRED for the AC — always coerced (a partial row → "").
    seenDate: asString(r.seenDate),
    ...(sourceCountry !== "" ? { sourceCountry } : {}),
    ...(sourceLanguage !== "" ? { sourceLanguage } : {}),
    ...(thumbnailUrl !== "" ? { thumbnailUrl } : {}),
  };
}

/**
 * buildNewsBody — assemble the request body per the BFF contract, including a
 * field ONLY when it is meaningfully set: worldwide omits countryCode, "any"
 * time is omitted, a blank/whitespace domain is omitted, the default "articles"
 * type is omitted, and "broadcast" (DEFERRED) is NEVER sent. There is no
 * safeSearch field for News.
 */
function buildNewsBody(
  query: string,
  options: NewsSearchOptions,
): Record<string, unknown> {
  const body: Record<string, unknown> = { query };
  if (options.count !== undefined) body.count = options.count;
  if (options.countryCode) body.countryCode = options.countryCode;
  if (options.timeRange !== undefined && options.timeRange !== "any") {
    body.timeRange = options.timeRange;
  }
  const domain = options.domain?.trim() ?? "";
  if (domain !== "") body.domain = domain;
  // Send only a real, shippable non-default type: "images". The "articles"
  // default is equivalent to UNSPECIFIED at the service, and "broadcast" is
  // deferred (UNIMPLEMENTED) — neither reaches the wire.
  if (options.resultType === "images") body.resultType = "images";
  if (options.targetLocale) body.targetLocale = options.targetLocale;
  return body;
}

/**
 * executeNewsSearch — POST /api/v1/monitor/news.
 *
 * Sends `{ query, ...filters/country/locale }` as JSON with the session cookie,
 * throws a MonitorApiError (carrying the HTTP status and any Retry-After) on any
 * non-2xx response, and maps the success envelope into a NewsSearchResponse.
 * Each optional field reaches the body only when meaningfully set (see
 * buildNewsBody). A missing / non-array `results` maps to an empty list.
 */
export async function executeNewsSearch(
  query: string,
  options?: NewsSearchOptions,
  signal?: AbortSignal,
): Promise<NewsSearchResponse> {
  const res = await fetch("/api/v1/monitor/news", {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(buildNewsBody(query, options ?? {})),
