/**
 * scrape.ts — typed fetch wrapper for the Web Scraper (tickets #1154 + #1155).
 *
 *   POST /api/v1/monitor/scrape  { "url": string, "engine": "default" | "reader" }
 *     — 200 + the standard monitor-bff envelope:
 *       { "data": { "title", "source", "engine", "wordCount",
 *                   "language", "markdown" } }
 *       source = host, engine echoes the requested engine back, wordCount is a
 *       number, language + markdown are strings.
 *
 * Backed end-to-end by monitor-bff's POST /api/v1/monitor/scrape route, which
 * forwards to monitor-svc's Scrape RPC (fetch + extract to markdown). This
 * module is typed plumbing: POST the URL + engine as JSON with the session
 * cookie, unwrap the envelope, and coerce each field into the readonly
 * ScrapedPageDTO the UI reads. It never fabricates content; a missing field
 * maps to 0 / "" via asNumber / asString. Mirrors dashboard.ts / activity.ts.
 */

import { asNumber, asString, parseError, unwrap } from "./client";

/** The two extraction engines the options row offers (ticket #1155). */
export type ScrapeEngine = "default" | "reader";

/** The cleaned page returned by a scrape — readonly, UI-facing shape. */
export interface ScrapedPageDTO {
  /** Page title, from the source document's <title> / main heading. */
  readonly title: string;
  /**
   * The resolved URL the server actually fetched, after following redirects.
   * This is what "View original" links to, so the link points at the page the
   * returned content came from. monitor-svc rejects any non-http(s) target
   * before fetching, so this is always an http(s) URL — never the raw string
   * the user typed.
   */
  readonly url: string;
  /** Source host (e.g. "example.com"), shown in the result header. */
  readonly source: string;
  /** The engine that produced this result — echoes the requested engine. */
  readonly engine: string;
  /** Word count of the extracted body. */
  readonly wordCount: number;
  /** BCP-47-ish language code of the extracted content (e.g. "en"). */
  readonly language: string;
  /** The extracted content as markdown — cleaned (reader) or raw (default). */
  readonly markdown: string;
  /**
   * A base64 PNG data URL (`data:image/png;base64,...`) of the full-page
   * capture — present ONLY on a Default-engine result that captured one, absent
   * otherwise (Reader never captures). Undefined, never "", when absent.
   */
  readonly screenshot?: string;
}

/**
 * scrapePage — POST /api/v1/monitor/scrape.
 *
 * Sends `{ url, engine, captureScreenshot }` as JSON with the session cookie,
 * throws a MonitorApiError (carrying the HTTP status) on any non-2xx response,
 * and maps the success envelope into ScrapedPageDTO. `signal` threads an
 * AbortController so an overlapping / cancelled scrape aborts in flight.
 *
 * `captureScreenshot` requests a full-page screenshot; the backend honours it
 * only for the Default engine (Reader never captures). An empty `screenshot`
 * field maps to `undefined` (absent), never "" — the result card must not
 * render an image block for a page that captured none.
 */
export async function scrapePage(
  url: string,
  engine: ScrapeEngine,
  captureScreenshot: boolean,
  signal?: AbortSignal,
): Promise<ScrapedPageDTO> {
  const res = await fetch("/api/v1/monitor/scrape", {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ url, engine, captureScreenshot }),
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const d = unwrap(await res.json()) as Record<string, unknown>;
  const screenshot = asString(d.screenshot);
  return {
    title: asString(d.title),
    url: asString(d.url),
    source: asString(d.source),
    engine: asString(d.engine),
    wordCount: asNumber(d.wordCount),
    language: asString(d.language),
    markdown: asString(d.markdown),
    // Only include when non-empty so `screenshot` is undefined (absent) rather
    // than "" when no capture was returned.
    ...(screenshot ? { screenshot } : {}),
  };
}


