/**
 * trends.ts — typed fetch wrappers for the Monitor Trends surface
 * (#1143 dashboard + #1145 create dialog).
 *
 *   GET  /api/v1/monitor/trends        — list the user's trend monitors
 *   POST /api/v1/monitor/trends        — create a trend monitor
 *
 * All calls go through monitor-bff and share the standard `{ data: ... }`
 * envelope (see client.ts). Snake_case DTO fields map to the camelCase shapes
 * the UI reads; the platform enum maps to/from the protojson enum names in
 * omnicore/monitor/trend/v1 (Platform) — the canonical wire representation the
 * Go BFF unmarshals straight into the proto enum.
 */

import { parseError, unwrap } from "./client";

/** UI-facing platform id — one monitor watches exactly one platform. */
export type TrendPlatform = "google" | "x" | "tiktok" | "range";

/** A trend monitor as the UI reads it (camelCase). */
export interface TrendMonitor {
  readonly id: string;
  readonly name: string;
  readonly description: string;
  readonly platform: TrendPlatform;
  /** Verbatim display label the user chose; blank = no restriction. */
  readonly regionLabel: string;
  readonly timeframe: string;
  readonly checkFrequency: string;
  /** The tracked terms/keywords; the rail shows the count. Default []. */
  readonly keywords: readonly string[];
  /** Set only when platform === "range". */
  readonly exerciseId: string;
  /** ISO timestamp the monitor was created; present only when the wire carries
   *  it (edit dialog shows a "created" sub-line when available, honest when not). */
  readonly createdAt?: string;
}

export interface CreateTrendMonitorRequest {
  readonly name: string;
  readonly description: string;
  readonly platform: TrendPlatform;
  readonly regionLabel: string;
  readonly timeframe: string;
  readonly checkFrequency: string;
  readonly exerciseId: string;
}

/**
 * The editable subset of a trend monitor (#1146). Every field is optional: an
 * ABSENT key means "leave unchanged" on the wire, so the dialog sends only the
 * fields the user actually touched. `regionLabel` is sent VERBATIM, including
 * "" — the legitimate "clear to Worldwide" value, which must NOT be confused
 * with "not provided". Platform is not editable (it locks the snapshot history).
 */
export interface UpdateTrendMonitorRequest {
  readonly name?: string;
  readonly description?: string;
  readonly regionLabel?: string;
  readonly timeframe?: string;
  readonly checkFrequency?: string;
  readonly keywords?: readonly string[];
}

// ─── platform ↔ wire mapping ────────────────────────────────────────────────
//
// The wire form is the protojson enum name (omnicore.monitor.trend.v1.Platform).
// Numeric enum values are also tolerated on read (protojson may emit either),
// and an unknown/unspecified value defaults to "google" — the honest, safe
// default for a monitor row missing its platform.

const PLATFORM_TO_WIRE: Record<TrendPlatform, string> = {
  google: "PLATFORM_GOOGLE_TRENDS",
  x: "PLATFORM_X",
  tiktok: "PLATFORM_TIKTOK",
  range: "PLATFORM_RANGE_EXERCISE",
};

const WIRE_TO_PLATFORM: Record<string, TrendPlatform> = {
  PLATFORM_GOOGLE_TRENDS: "google",
  "1": "google",
  PLATFORM_X: "x",
  "2": "x",
  PLATFORM_TIKTOK: "tiktok",
  "3": "tiktok",
  PLATFORM_RANGE_EXERCISE: "range",
  "4": "range",
};

function toPlatform(raw: unknown): TrendPlatform {
  return WIRE_TO_PLATFORM[String(raw ?? "")] ?? "google";
}

function asString(v: unknown): string {
  return typeof v === "string" ? v : "";
}

/** A read-tolerant string array: non-arrays → [], non-string members dropped. */
function asStringArray(v: unknown): string[] {
  return Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : [];
}

function mapMonitor(raw: Record<string, unknown>): TrendMonitor {
  const base: TrendMonitor = {
    id: asString(raw.id),
    name: asString(raw.name),
    description: asString(raw.description),
    platform: toPlatform(raw.platform),
    regionLabel: asString(raw.region_label),
    timeframe: asString(raw.timeframe),
    checkFrequency: asString(raw.check_frequency),
    keywords: asStringArray(raw.keywords),
    exerciseId: asString(raw.exercise_id),
  };
  // created_at is optional on the wire; only surface `createdAt` when present so
  // callers can honestly omit the "created" line when the backend didn't send it.
  return raw.created_at === undefined
    ? base
    : { ...base, createdAt: asString(raw.created_at) };
}

function asRecord(v: unknown): Record<string, unknown> {
  return v !== null && typeof v === "object"
    ? (v as Record<string, unknown>)
    : {};
}

/** One page of the user's trend monitors, plus the token for the next page. */
export interface TrendMonitorPage {
  readonly monitors: TrendMonitor[];
  /** Opaque token for the next page; "" when there are no more pages. */
  readonly nextPageToken: string;
}

/**
 * GET /api/v1/monitor/trends — one page of the user's trend monitors.
 *
 * We rely on the monitor-svc default page size (it defaults sensibly and clamps),
 * so `page_size` is never sent. Pass a non-empty `pageToken` to fetch the next
 * page (surfaced as `?page_token=<token>`); the response's `next_page_token` is
 * read back off the envelope (missing/empty ⇒ ""). An empty page ⇒ `{ monitors: [],
 * nextPageToken: "" }`.
 */
export async function listTrendMonitors(
  pageToken?: string,
  signal?: AbortSignal,
): Promise<TrendMonitorPage> {
  const url =
    pageToken && pageToken.length > 0
      ? `/api/v1/monitor/trends?page_token=${encodeURIComponent(pageToken)}`
      : "/api/v1/monitor/trends";
  const res = await fetch(url, {
    credentials: "include",
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const root = unwrap(await res.json()) as Record<string, unknown>;
  const rows = root.trends;
  const monitors = Array.isArray(rows)
    ? rows.map((r) => mapMonitor(asRecord(r)))
    : [];
  return { monitors, nextPageToken: asString(root.next_page_token) };
}

/** POST /api/v1/monitor/trends — create a monitor, return the created row. */
export async function createTrendMonitor(
  req: CreateTrendMonitorRequest,
  signal?: AbortSignal,
): Promise<TrendMonitor> {
  const body = {
    name: req.name,
    description: req.description,
    platform: PLATFORM_TO_WIRE[req.platform],
    region_label: req.regionLabel,
    timeframe: req.timeframe,
    check_frequency: req.checkFrequency,
    keywords: [] as string[],
    exercise_id: req.exerciseId,
  };

  const res = await fetch("/api/v1/monitor/trends", {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const root = unwrap(await res.json()) as Record<string, unknown>;
  return mapMonitor(asRecord(root.trend));
}

/**
 * PUT /api/v1/monitor/trends/{id} — update an existing monitor (#1146).
 *
 * Only the fields present on `req` are put on the wire (absent key ⇒ leave
 * unchanged). `regionLabel` maps to `region_label` VERBATIM — including "" to
 * clear the region back to Worldwide — so a deliberate clear is never dropped as
 * if it were "not provided" (the class of "silently dropped in production").
 * Returns the updated monitor; a non-2xx throws (mirrors createTrendMonitor).
 */
export async function updateTrendMonitor(
  id: string,
  req: UpdateTrendMonitorRequest,
  signal?: AbortSignal,
): Promise<TrendMonitor> {
  const body: Record<string, unknown> = {};
  if (req.name !== undefined) body.name = req.name;
  if (req.description !== undefined) body.description = req.description;
  if (req.regionLabel !== undefined) body.region_label = req.regionLabel;
  if (req.timeframe !== undefined) body.timeframe = req.timeframe;
  if (req.checkFrequency !== undefined) body.check_frequency = req.checkFrequency;
  if (req.keywords !== undefined) body.keywords = req.keywords;

  const res = await fetch(`/api/v1/monitor/trends/${id}`, {
    method: "PUT",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
    signal,
  });
  if (!res.ok) throw await parseError(res);

  const root = unwrap(await res.json()) as Record<string, unknown>;
  return mapMonitor(asRecord(root.trend));
}

/**
 * DELETE /api/v1/monitor/trends/{id} — delete a monitor (#1147).
 *
 * monitor-bff answers a successful delete with 204 No Content (empty body), so
 * there is NO envelope to unwrap — any 2xx is success and we resolve void. A
 * non-2xx throws a MonitorApiError (mirrors updateTrendMonitor). The optional
 * AbortSignal lets a caller cancel an in-flight delete.
 */
export async function deleteTrendMonitor(
  id: string,
  signal?: AbortSignal,
): Promise<void> {
  const res = await fetch(`/api/v1/monitor/trends/${id}`, {
    method: "DELETE",
    credentials: "include",
    signal,
  });
  if (!res.ok) throw await parseError(res);
}



